hf_controller_content = '''#!/usr/bin/env python3
"""
The New Civilization - Hugging Face API Controller
Ultra-lightweight AI model management and inference

Copyright (c) 2024 The New Civilization Project
Licensed under MIT License
"""

import os
import json
import time
import logging
from datetime import datetime
from typing import Dict, Any, Optional, List
import urllib.request
import urllib.parse
import urllib.error

class HuggingFaceController:
    """Ultra-lightweight Hugging Face API controller with zero heavy dependencies"""

    def __init__(self, token: Optional[str] = None):
        """
        Initialize HF controller

        Args:
            token: Hugging Face API token
        """
        self.token = token or os.getenv('HF_TOKEN', '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')
        self.api_base = 'https://api-inference.huggingface.co/models'
        self.headers = {
            'Authorization': f'Bearer {self.token}',
            'Content-Type': 'application/json'
        }

        # Setup logging
        self.logger = logging.getLogger(__name__)

        # Model registry - curated for reliability and speed
        self.models = {
            'text_generation': {
                'default': 'microsoft/DialoGPT-medium',
                'fast': 'gpt2',
                'multilingual': 'microsoft/DialoGPT-large'
            },
            'sentiment_analysis': {
                'default': 'cardiffnlp/twitter-roberta-base-sentiment-latest',
                'fast': 'distilbert-base-uncased-finetuned-sst-2-english'
            },
            'summarization': {
                'default': 'facebook/bart-large-cnn',
                'fast': 'sshleifer/distilbart-cnn-12-6'
            },
            'translation': {
                'en_to_fr': 'Helsinki-NLP/opus-mt-en-fr',
                'en_to_es': 'Helsinki-NLP/opus-mt-en-es',
                'en_to_de': 'Helsinki-NLP/opus-mt-en-de',
                'multilingual': 'Helsinki-NLP/opus-mt-mul-en'
            },
            'question_answering': {
                'default': 'deepset/roberta-base-squad2',
                'fast': 'distilbert-base-uncased-distilled-squad'
            },
            'text_classification': {
                'default': 'cardiffnlp/twitter-roberta-base-sentiment-latest',
                'emotion': 'j-hartmann/emotion-english-distilroberta-base'
            }
        }

        # Usage tracking
        self.request_count = 0
        self.last_request_time = None

    def query_model(self, model_name: str, payload: Dict[str, Any], 
                   max_retries: int = 3, timeout: int = 60) -> Dict[str, Any]:
        """
        Query a Hugging Face model with comprehensive error handling

        Args:
            model_name: Name of the model to query
            payload: Input payload for the model
            max_retries: Maximum number of retry attempts
            timeout: Request timeout in seconds

        Returns:
            Dict containing success status and response data
        """
        url = f"{self.api_base}/{model_name}"
        data = json.dumps(payload).encode('utf-8')

        for attempt in range(max_retries):
            try:
                # Rate limiting check
                if self.last_request_time:
                    time_diff = time.time() - self.last_request_time
                    if time_diff < 0.1:  # Minimum 100ms between requests
                        time.sleep(0.1 - time_diff)

                # Make request
                request = urllib.request.Request(url, data=data, headers=self.headers)

                with urllib.request.urlopen(request, timeout=timeout) as response:
                    result = json.loads(response.read().decode('utf-8'))

                    # Update tracking
                    self.request_count += 1
                    self.last_request_time = time.time()

                    self.logger.info(f"✅ Model query successful: {model_name}")
                    return {
                        'success': True,
                        'data': result,
                        'model': model_name,
                        'timestamp': datetime.now().isoformat()
                    }

            except urllib.error.HTTPError as e:
                error_msg = f"HTTP {e.code}: {e.reason}"

                if e.code == 503:  # Model loading
                    if attempt < max_retries - 1:
                        wait_time = 2 ** attempt
                        self.logger.warning(f"⏳ Model loading, waiting {wait_time}s...")
                        time.sleep(wait_time)
                        continue
                    else:
                        error_msg = "Model unavailable after retries"
                elif e.code == 429:  # Rate limited
                    wait_time = 1 * (attempt + 1)
                    self.logger.warning(f"⚠️ Rate limited, waiting {wait_time}s...")
                    time.sleep(wait_time)
                    continue
                elif e.code == 401:
                    error_msg = "Invalid API token"

                self.logger.error(f"❌ HTTP Error: {error_msg}")
                return {
                    'success': False,
                    'error': error_msg,
                    'model': model_name,
                    'timestamp': datetime.now().isoformat()
                }

            except urllib.error.URLError as e:
                error_msg = f"Network error: {e.reason}"
                self.logger.error(f"❌ Network Error: {error_msg}")
                return {
                    'success': False,
                    'error': error_msg,
                    'model': model_name,
                    'timestamp': datetime.now().isoformat()
                }

            except json.JSONDecodeError as e:
                error_msg = f"Invalid JSON response: {str(e)}"
                self.logger.error(f"❌ JSON Error: {error_msg}")
                return {
                    'success': False,
                    'error': error_msg,
                    'model': model_name,
                    'timestamp': datetime.now().isoformat()
                }

            except Exception as e:
                error_msg = f"Unexpected error: {str(e)}"
                self.logger.error(f"❌ Unexpected Error: {error_msg}")
                return {
                    'success': False,
                    'error': error_msg,
                    'model': model_name,
                    'timestamp': datetime.now().isoformat()
                }

        # Max retries exceeded
        error_msg = f"Max retries ({max_retries}) exceeded"
        self.logger.error(f"❌ {error_msg}")
        return {
            'success': False,
            'error': error_msg,
            'model': model_name,
            'timestamp': datetime.now().isoformat()
        }

    # ======================
    # AI Service Methods
    # ======================

    def generate_text(self, prompt: str, max_length: int = 50, 
                     model_type: str = 'default') -> Dict[str, Any]:
        """Generate text using language models"""
        model_name = self.models['text_generation'][model_type]
        payload = {
            'inputs': prompt,
            'parameters': {
                'max_length': max_length,
                'temperature': 0.7,
                'return_full_text': False,
                'do_sample': True
            }
        }
        return self.query_model(model_name, payload)

    def analyze_sentiment(self, text: str, 
                         model_type: str = 'default') -> Dict[str, Any]:
        """Analyze sentiment of text"""
        model_name = self.models['sentiment_analysis'][model_type]
        payload = {'inputs': text}
        return self.query_model(model_name, payload)

    def summarize_text(self, text: str, max_length: int = 100, 
                      min_length: int = 30, model_type: str = 'default') -> Dict[str, Any]:
        """Summarize text content"""
        model_name = self.models['summarization'][model_type]
        payload = {
            'inputs': text,
            'parameters': {
                'max_length': max_length,
                'min_length': min_length,
                'do_sample': False
            }
        }
        return self.query_model(model_name, payload)

    def translate_text(self, text: str, 
                      language_pair: str = 'en_to_fr') -> Dict[str, Any]:
        """Translate text between languages"""
        model_name = self.models['translation'][language_pair]
        payload = {'inputs': text}
        return self.query_model(model_name, payload)

    def answer_question(self, question: str, context: str, 
                       model_type: str = 'default') -> Dict[str, Any]:
        """Answer question based on context"""
        model_name = self.models['question_answering'][model_type]
        payload = {
            'inputs': {
                'question': question,
                'context': context
            }
        }
        return self.query_model(model_name, payload)

    def classify_text(self, text: str, 
                     model_type: str = 'default') -> Dict[str, Any]:
        """Classify text content"""
        model_name = self.models['text_classification'][model_type]
        payload = {'inputs': text}
        return self.query_model(model_name, payload)

    # ======================
    # Utility Methods
    # ======================

    def get_available_models(self) -> Dict[str, Any]:
        """Get list of available models"""
        return {
            'models': self.models,
            'total_categories': len(self.models),
            'request_count': self.request_count,
            'last_request': self.last_request_time
        }

    def health_check(self) -> Dict[str, Any]:
        """Perform health check on the controller"""
        return {
            'status': 'healthy',
            'api_token_set': bool(self.token and self.token != 'your_token_here'),
            'models_loaded': len(self.models),
            'request_count': self.request_count,
            'timestamp': datetime.now().isoformat()
        }

    def get_stats(self) -> Dict[str, Any]:
        """Get usage statistics"""
        return {
            'total_requests': self.request_count,
            'last_request_time': self.last_request_time,
            'available_services': list(self.models.keys()),
            'total_models': sum(len(category) for category in self.models.values()),
            'uptime': time.time() - (self.last_request_time or time.time())
        }

# Factory function for easy instantiation
def create_hf_controller(token: Optional[str] = None) -> HuggingFaceController:
    """Create and return a HuggingFace controller instance"""
    return HuggingFaceController(token)
'''

